export const DEMO_YAML = "# Synthetic cluster snapshot used by the test suite and the in-app demo.\n#\n# It is a \"messy but realistic\" dump: namespaced SAs, a CI SA that looks\n# harmless, a ServiceAccount with a single `impersonate serviceaccounts` rule,\n# an aggregate ClusterRole, and token Secrets. Each planted escalation path is\n# listed in fixtures/README.md.\n---\napiVersion: v1\nkind: Namespace\nmetadata: {name: ci}\n---\napiVersion: v1\nkind: Namespace\nmetadata: {name: metrics}\n---\napiVersion: v1\nkind: Namespace\nmetadata: {name: payments}\n---\napiVersion: v1\nkind: Namespace\nmetadata: {name: kube-system}\n---\n# ---------------------------------------------------------------- SAs\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: builder, namespace: ci}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: deployer, namespace: ci}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: cert-bot, namespace: ci}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: prometheus, namespace: metrics}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: breakglass, namespace: payments}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: default, namespace: ci}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: default, namespace: metrics}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: default, namespace: payments}\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata: {name: default, namespace: kube-system}\n---\n\n# ===========================================================================\n# PATH A — \"the CI runner only creates Pods\"\n#\n#   ci/builder  --create pods-->  ci/deployer  --bind cluster-admin--> cluster-admin\n#\n# builder cannot touch RBAC at all. It only creates Pods in ci, which lets it\n# take on deployer's identity; deployer holds the classic `bind` + `create\n# clusterrolebindings` pair.\n# ===========================================================================\napiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata: {name: ci-pod-runner, namespace: ci}\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"pods\", \"pods/exec\"]\n    verbs: [\"create\", \"get\", \"list\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata: {name: ci-pod-runner-binding, namespace: ci}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: Role, name: ci-pod-runner}\nsubjects:\n  - {kind: ServiceAccount, name: builder, namespace: ci}\n---\n# deployer's own role looks like a normal \"deploy apps\" role.\napiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata: {name: deployer-role, namespace: ci}\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"pods\", \"services\", \"configmaps\", \"secrets\"]\n    verbs: [\"*\"]\n  - apiGroups: [\"apps\"]\n    resources: [\"deployments\"]\n    verbs: [\"*\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata: {name: deployer-binding, namespace: ci}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: Role, name: deployer-role}\nsubjects:\n  - {kind: ServiceAccount, name: deployer, namespace: ci}\n---\n# The escalation primitive: bind any of the grantable ClusterRoles.\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: release-binding-granter}\nrules:\n  - apiGroups: [\"rbac.authorization.k8s.io\"]\n    resources: [\"clusterrolebindings\"]\n    verbs: [\"create\"]\n  - apiGroups: [\"rbac.authorization.k8s.io\"]\n    resources: [\"clusterroles\"]\n    resourceNames: [\"admin\", \"edit\", \"view\", \"cluster-admin\"]\n    verbs: [\"bind\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: release-binding-granter-binding}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: release-binding-granter}\nsubjects:\n  - {kind: ServiceAccount, name: deployer, namespace: ci}\n---\n\n# ===========================================================================\n# PATH B — \"a metrics SA that can only impersonate in its own namespace\"\n#\n#   metrics/default --impersonate SA--> metrics/prometheus\n#                   --escalate its own ClusterRole--> cluster-admin\n#\n# Neither link looks dangerous alone: impersonation is namespace-scoped, and\n# `escalate` only edits a role prometheus is already bound to. Together they\n# reach the top because the aggregated rules of that role are then wildcarded.\n# ===========================================================================\napiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata: {name: sa-impersonator, namespace: metrics}\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"serviceaccounts\"]\n    verbs: [\"impersonate\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata: {name: sa-impersonator-binding, namespace: metrics}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: Role, name: sa-impersonator}\nsubjects:\n  - {kind: ServiceAccount, name: default, namespace: metrics}\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: metrics-scraper-cluster}\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"nodes\", \"pods\", \"services\", \"endpoints\"]\n    verbs: [\"get\", \"list\", \"watch\"]\n  - apiGroups: [\"metrics.k8s.io\"]\n    resources: [\"*\"]\n    verbs: [\"*\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: prometheus-scraper}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: metrics-scraper-cluster}\nsubjects:\n  - {kind: ServiceAccount, name: prometheus, namespace: metrics}\n---\n# prometheus may maintain its own ClusterRole — but `escalate` means it may\n# write `*` into it, and it is already bound to it.\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: metrics-role-editor}\nrules:\n  - apiGroups: [\"rbac.authorization.k8s.io\"]\n    resources: [\"clusterroles\"]\n    resourceNames: [\"metrics-scraper-cluster\"]\n    verbs: [\"update\", \"patch\"]\n  - apiGroups: [\"rbac.authorization.k8s.io\"]\n    resources: [\"clusterroles\"]\n    resourceNames: [\"metrics-scraper-cluster\"]\n    verbs: [\"escalate\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: metrics-role-editor-binding}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: metrics-role-editor}\nsubjects:\n  - {kind: ServiceAccount, name: prometheus, namespace: metrics}\n---\n\n# ===========================================================================\n# PATH C — \"aggregation hides a Secret reader behind a breakglass SA\"\n#\n#   payments/default --aggregated ClusterRole--> get secrets in payments\n#                    --read token Secret--> payments/breakglass\n#                    --ClusterRoleBinding to cluster-admin--> cluster-admin\n#\n# The aggregated ClusterRole has an empty `rules:` field. Unless you expand it\n# you see no permissions at all.\n# ===========================================================================\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: payments-operator}\naggregationRule:\n  clusterRoleSelectors:\n    - matchLabels:\n        rbac.example.com/aggregate-to-payments: \"true\"\nrules: []\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata:\n  name: payments-operator-secrets\n  labels:\n    rbac.example.com/aggregate-to-payments: \"true\"\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"secrets\"]\n    verbs: [\"get\", \"list\", \"watch\"]\n  - apiGroups: [\"\"]\n    resources: [\"serviceaccounts/token\"]\n    verbs: [\"create\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata: {name: payments-operator-binding, namespace: payments}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: payments-operator}\nsubjects:\n  - {kind: ServiceAccount, name: default, namespace: payments}\n---\n# A break-glass SA with cluster-admin, kept \"for emergencies\". Reaching its\n# token is the whole point of the Secret read above.\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: breakglass-admin}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: cluster-admin}\nsubjects:\n  - {kind: ServiceAccount, name: breakglass, namespace: payments}\n---\napiVersion: v1\nkind: Secret\nmetadata:\n  name: breakglass-token\n  namespace: payments\n  annotations:\n    kubernetes.io/service-account.name: breakglass\ntype: kubernetes.io/service-account-token\ndata: {token: c2VjcmV0, ca.crt: Y2E=, namespace: cGF5bWVudHM=}\n---\n\n# ===========================================================================\n# PATH D — impersonating a group (hidden)\n#\n#   alice --impersonate groups--> system:masters  == cluster-admin\n#\n# `system:masters` bypasses RBAC entirely inside the API server, so no\n# ClusterRoleBinding is required.\n# ===========================================================================\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: group-impersonator}\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"groups\"]\n    verbs: [\"impersonate\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: group-impersonator-binding}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: group-impersonator}\nsubjects:\n  - {kind: User, name: alice@example.com}\n---\n\n# ===========================================================================\n# PATH E — CSR forging (hidden)\n#\n#   ci/cert-bot --create CSR + approve signers/kubernetes.io/*--> cluster-admin\n# ===========================================================================\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata: {name: csr-issuer}\nrules:\n  - apiGroups: [\"certificates.k8s.io\"]\n    resources: [\"certificatesigningrequests\"]\n    verbs: [\"create\", \"get\", \"list\", \"watch\"]\n  - apiGroups: [\"certificates.k8s.io\"]\n    resources: [\"certificatesigningrequests/approval\"]\n    verbs: [\"update\"]\n  - apiGroups: [\"certificates.k8s.io\"]\n    resources: [\"signers\"]\n    resourceNames: [\"kubernetes.io/kube-apiserver-client\"]\n    verbs: [\"approve\"]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata: {name: csr-issuer-binding}\nroleRef: {apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: csr-issuer}\nsubjects:\n  - {kind: ServiceAccount, name: cert-bot, namespace: ci}\n---\n\n# ===========================================================================\n# Objects used by the reverse (\"who can read this namespace's Secrets\") query\n# ===========================================================================\napiVersion: v1\nkind: Secret\nmetadata:\n  name: deployer-token\n  namespace: ci\n  annotations:\n    kubernetes.io/service-account.name: deployer\ntype: kubernetes.io/service-account-token\ndata: {token: c2VjcmV0, ca.crt: Y2E=}\n---\napiVersion: v1\nkind: Secret\nmetadata:\n  name: db-password\n  namespace: payments\ntype: Opaque\ndata: {password: c2VjcmV0}\n---\napiVersion: v1\nkind: Pod\nmetadata:\n  name: payments-api-0\n  namespace: payments\n  labels: {app: payments-api}\nspec:\n  serviceAccountName: default\n  nodeName: node-a\n---\napiVersion: v1\nkind: Pod\nmetadata:\n  name: ci-runner\n  namespace: ci\n  labels: {app: ci-runner}\nspec:\n  serviceAccountName: builder\n  nodeName: node-a\n---\napiVersion: v1\nkind: Pod\nmetadata:\n  name: metrics-agent\n  namespace: metrics\nspec:\n  serviceAccountName: prometheus\n  nodeName: node-b\n";
